/**
 * Visibility and org-scope WHERE clause helpers:
 * buildOrgScopeWhere, buildConnectionVisibilityClause, buildExcludeWatcherClause.
 */

import { compileConnectionFkVisibility } from '../../authz/connection-visibility';
import { compileResourceVisibility } from '../../authz/resource-visibility';
import type { AuthzScope } from '../../authz/scope';
import { validateNumericId } from '../sql-validation';

/**
 * Build NOT EXISTS clause to exclude content already in any window for a given
 * watcher. The watcher id is both validated (integer check) and bound as a query
 * parameter — validation guards against obvious injection attempts and the
 * parameter binding is the real defense.
 *
 * @param excludeWatcherId - Watcher ID to exclude content for
 * @param baseParamIndex - Next 1-based `$N` index to allocate for bound params
 * @param tableAlias - Alias for the content table (default: 'f')
 * @returns `{ sql, params }` — empty strings/arrays when no filter is applied
 */
export function buildExcludeWatcherClause(
  excludeWatcherId: number | undefined,
  baseParamIndex: number,
  tableAlias = 'f'
): { sql: string; params: unknown[] } {
  if (excludeWatcherId === undefined) return { sql: '', params: [] };
  const validated = validateNumericId(excludeWatcherId, 'exclude_watcher_id');
  return {
    sql: ` AND NOT EXISTS (
    SELECT 1 FROM watcher_window_events exc_iwe
    WHERE exc_iwe.event_id = ${tableAlias}.id AND exc_iwe.watcher_id = $${baseParamIndex}::bigint
  )`,
    params: [validated],
  };
}

/**
 * Build an org/workspace-scoping WHERE clause using EXISTS (no JOIN needed).
 * Returns an empty string when no scoping is needed (e.g. entity_id is set).
 * Assumes the query has `f` aliasing events and `c` aliasing connections.
 *
 * An event is in scope when ANY of these hold:
 *  - the event itself was stamped to the caller's org (`f.organization_id`),
 *  - one of its `entity_ids` belongs to the caller's org, or
 *  - the connection that produced it belongs to the caller's org.
 *
 * The bridge clauses cover events ingested into another org but cross-linked
 * to entities/connections here. Stand-alone events with no entity links and
 * no connection are still findable via the direct `f.organization_id` match.
 */
export function buildOrgScopeWhere(options: {
  entity_id?: number;
  organization_id?: string;
  baseParamIndex: number;
}): { sql: string; params: Array<string | number | null> } {
  if (options.entity_id || !options.organization_id) return { sql: '', params: [] };

  const p = `$${options.baseParamIndex}::text`;
  const directCond = `f.organization_id = ${p}`;
  const entityCond = `EXISTS (SELECT 1 FROM entities ent_org WHERE ent_org.id = ANY(f.entity_ids) AND ent_org.organization_id = ${p})`;
  const connCond = `c.organization_id = ${p}`;
  return {
    sql: `AND (${directCond} OR ${entityCond} OR ${connCond})`,
    params: [options.organization_id],
  };
}

/**
 * Build a connection-visibility WHERE clause that lives inline alongside the
 * other content filters, so the list and count queries don't need a separate
 * "which connection ids may I see?" round trip.
 *
 * Semantics (must match `getContent`'s legacy two-step flow):
 *  - Authed user: connections with `visibility='org' OR created_by = $userId`.
 *  - Unauthed:    connections with `visibility='org'`.
 *  - Soft-deleted connections (`deleted_at IS NOT NULL`) are excluded.
 *  - Events with `connection_id IS NULL` (system / non-connection events)
 *    are visible in both authed and unauthed cases.
 *
 * Returns an empty fragment when no scope is requested (callers like the
 * behavior-mode path that already select by other constraints).
 *
 * Thin adapter over the one connection-visibility compiler (M1): builds an
 * {@link AuthzScope} from this seam's legacy `{ organizationId, userId }` shape
 * and defers the predicate to {@link compileConnectionFkVisibility}, so the rule
 * lives in exactly one place.
 */
export function buildConnectionVisibilityClause(
  options: {
    organizationId?: string;
    userId?: string | null;
    baseParamIndex: number;
  },
  tableAlias: string = 'f'
): { sql: string; params: Array<string | number | null> } {
  if (!options.organizationId) return { sql: '', params: [] };

  const scope: AuthzScope = {
    organizationId: options.organizationId,
    principal: options.userId ?? null,
  };
  // Compose the two read gates: per-connection visibility AND per-resource
  // membership (the latter only constrains ACL-enforced connections). Resource
  // visibility binds its own params AFTER the connection-visibility params, so a
  // single returned `{ sql, params }` keeps every caller's `$N` indexing intact.
  const conn = compileConnectionFkVisibility(scope, options.baseParamIndex, tableAlias);
  const resource = compileResourceVisibility(
    scope,
    options.baseParamIndex + conn.params.length,
    tableAlias,
  );
  return {
    sql: `${conn.sql} ${resource.sql}`,
    params: [...conn.params, ...resource.params],
  };
}

/**
 * Standard parameter-building helpers for the listing path:
 * buildStandardParams, buildStandardWhereSql, WINDOW_JOIN_SQL.
 */

import { pgTextArray } from '../../db/client';
import type { ContentSearchOptions } from './types';

export function buildStandardParams(
  options: ContentSearchOptions & { offset?: number },
  extra: {
    sinceDate: Date | null;
    untilDate: Date | null;
  }
): any[] {
  return [
    options.entity_id ?? null,
    options.platform ?? null,
    extra.sinceDate?.toISOString() ?? null,
    extra.untilDate?.toISOString() ?? null,
    options.window_id ?? null,
    options.engagement_min ?? null,
    options.engagement_max ?? null,
    options.classification_source ?? null,
    // Slot $9 binds a Postgres `text[]` literal (e.g. `'{note,summary}'`); the
    // standard WHERE template uses `= ANY($9::text[])`, covering single- and
    // multi-type callers with one predicate. We hand-format the literal because
    // `sql.unsafe(...)` binding doesn't auto-cast JS arrays.
    options.semantic_type
      ? pgTextArray(
          Array.isArray(options.semantic_type) ? options.semantic_type : [options.semantic_type]
        )
      : null,
    options.interaction_status ?? null,
    // Slot $11 — per-agent memory scope. WHERE template uses
    // `($11::text IS NULL OR f.metadata->>'agent_id' = $11::text)`.
    options.agent_id ?? null,
  ];
}

/**
 * Build the shared `WHERE` skeleton used by `listContentInternal` for both
 * its count and list queries.
 *
 * `entityLinkSql` is the per-request fragment for "which events belong to
 * this entity" — see `buildEntityLinkUnion`. Pre-computing it once and
 * passing it in avoids re-emitting (and re-planning) the 7-branch generic
 * UNION for every query.
 */
export function buildStandardWhereSql(entityLinkSql: string): string {
  return `($1::bigint IS NULL OR ${entityLinkSql})
          AND ($2::text IS NULL OR f.connector_key = $2::text)
          AND ($3::timestamptz IS NULL OR f.occurred_at >= $3::timestamptz)
          AND ($4::timestamptz IS NULL OR f.occurred_at <= $4::timestamptz)
          AND ($5::int IS NULL OR iwf.window_id = $5::int)
          AND ($6::numeric IS NULL OR f.score >= $6::numeric)
          AND ($7::numeric IS NULL OR f.score <= $7::numeric)
          AND ($8::text IS NULL OR EXISTS (
            SELECT 1 FROM event_classifications lc_source
            WHERE lc_source.event_id = f.id
              AND lc_source.source = $8::text
          ))
          AND ($9::text[] IS NULL OR f.semantic_type = ANY($9::text[]))
          AND ($10::text IS NULL OR f.interaction_status = $10::text)
          AND ($11::text IS NULL OR f.metadata->>'agent_id' = $11::text)`;
}

export const WINDOW_JOIN_SQL = `LEFT JOIN watcher_window_events iwf
          ON iwf.event_id = f.id
          AND ($5::int IS NOT NULL)
          AND iwf.window_id = $5::int`;

/**
 * THE generic resource-visibility compiler — gates connector-sourced `events`
 * (GitHub issues/PRs, Linear issues, …) by RESOURCE membership, the same way
 * `./channel-visibility` gates Slack chat by channel membership, but at the
 * `events` read seam and for ANY resource type at once.
 *
 * Rule, composed AFTER the per-connection visibility gate (they AND together),
 * mirroring the three-state enforcement split `getConnectionEnforcement` /
 * `./channel-visibility` apply so the two gates can never drift:
 *   - an event on a connection that was NEVER graphed (no `authz_source_acl_state`
 *     row) is unconstrained here — the per-connection gate already decided it and
 *     an absent graph must never silently hide data;
 *   - an event on an ENFORCED connection (`acl_support='full'`,
 *     `freshness_state='fresh'`, synced within the freshness window) is visible
 *     ONLY when the requester is `member_of` one of the RESOURCE entities the
 *     event is linked to (`events.entity_ids`), where "resource" = an entity whose
 *     type is `$resource`. Scoped so the coarse person→`company` (org)
 *     `member_of` edge never satisfies it — org membership must NOT grant
 *     repo-level read;
 *   - an event on an onboarded-but-STALE connection (a row exists but is
 *     partial/failed/stale/aged-out — i.e. NOT in the enforced set) FAILS CLOSED:
 *     neither the not-graphed passthrough nor the enforced membership branch
 *     matches, so its resource-linked events are dropped rather than served on
 *     stale membership. Once a connection is graphed, it never falls back to the
 *     legacy per-connection fence — a stalled sync hides data, it does not leak it.
 *
 * Fail-closed: a headless/null principal, an enforced-connection event linked to
 * no resource the requester belongs to, or any event on a stale connection is
 * dropped. Generic across sources — GitHub repos and Linear teams gate
 * identically; a new source needs only a registry entry (`./sources`) plus its
 * connector stamping the resource identity on its events so they link to the
 * resource entity.
 */

import { ACL_RESOURCE_TYPE_SLUG } from '@lobu/connector-sdk';
import { aclStateExistsSelectSql, enforcedConnectionsSelectSql } from './acl-state.js';
import type { AuthzScope } from './scope.js';

/** Sole ACL resource type slug, inlined as a SQL string literal (constant). */
const RESOURCE_TYPE_SQL = `'${ACL_RESOURCE_TYPE_SLUG}'`;

/**
 * Predicate for a table holding events (alias has `connection_id` + `entity_ids`).
 * Binds two params from `baseParamIndex`: the org id and the principal. Returns an
 * `AND (...)` fragment (no leading space). Compose alongside
 * `compileConnectionFkVisibility` at the same seam.
 */
export function compileResourceVisibility(
  scope: AuthzScope,
  baseParamIndex: number,
  tableAlias: string,
): { sql: string; params: Array<string | null> } {
  const orgParam = `$${baseParamIndex}::text`;
  const userParam = `$${baseParamIndex + 1}::text`;

  // `events.connection_id` is the bigint `connections.id`, but
  // `authz_source_acl_state.connection_id` is text — the ACL sync stamps it as
  // `String(connections.id)` (see `github-acl-sync` → `buildAccessGraph`). Cast
  // `events.connection_id::text` so BOTH the "is this connection graphed?" check
  // and the "is it enforced?" check compare on the SAME key.
  //
  // Three-state split (mirrors `getConnectionEnforcement`), NOT a bare
  // `NOT IN (enforced)`:
  //   1. no ACL row for the connection → passthrough (never graphed → legacy fence);
  //   2. row is enforced (in the fresh-enforced set) → require the member_of EXISTS;
  //   3. row exists but is NOT enforced (stale/partial/failed/aged-out) → neither
  //      branch matches → FAIL CLOSED. A bare `NOT IN (enforced)` would make (3)
  //      true and leak stale-connection events to non-members — the hole this fix
  //      closes, matching the channel gate.
  const sql = `AND (
      ${tableAlias}.connection_id IS NULL
      OR ${tableAlias}.connection_id::text NOT IN (${aclStateExistsSelectSql(orgParam)})
      OR (${tableAlias}.connection_id::text IN (${enforcedConnectionsSelectSql(orgParam)})
      AND EXISTS (
        SELECT 1
        FROM public.entity_relationships rr
        JOIN public.entity_relationship_types rt
          ON rt.id = rr.relationship_type_id
         AND rt.organization_id = rr.organization_id
         AND rt.slug = 'member_of'
        JOIN public.entities re
          ON re.id = rr.to_entity_id
         AND re.organization_id = rr.organization_id
         AND re.deleted_at IS NULL
        JOIN public.entity_types ret
          ON ret.id = re.entity_type_id
         AND ret.organization_id = re.organization_id
         AND ret.slug = ${RESOURCE_TYPE_SQL}
        WHERE rr.organization_id = ${orgParam}
          AND rr.deleted_at IS NULL
          AND rr.to_entity_id = ANY(${tableAlias}.entity_ids)
          AND rr.from_entity_id = (
            SELECT mei.entity_id
            FROM public.entity_identities mei
            JOIN public.entities me
              ON me.id = mei.entity_id
             AND me.organization_id = mei.organization_id
             AND me.deleted_at IS NULL
            JOIN public.entity_types met
              ON met.id = me.entity_type_id
             AND met.organization_id = me.organization_id
             AND met.slug = '$member'
            WHERE mei.organization_id = ${orgParam}
              AND mei.namespace = 'auth_user_id'
              AND mei.identifier = ${userParam}
              AND mei.source_connector = 'auth:signup'
              AND mei.deleted_at IS NULL
            LIMIT 1
          )
      ))
    )`;
  return { sql, params: [scope.organizationId, scope.principal] };
}

