const MEMORY_TYPES = [
	"note",
	"summary",
	"decision",
	"observation",
	"fact",
	"change",
	"preference",
	"identity",
];
const BUCKETS: Array<{ key: Bucket; label: string; types: string[] }> = [
	{ key: "all", label: "All", types: [] },
	{ key: "notifications", label: "Alerts", types: NOTIFICATION_TYPES },
	{ key: "memory", label: "Saved notes", types: MEMORY_TYPES },
];

/** Matches `applyEventTabDefaults` — newest-first date feed is the baseline. */
const DEFAULT_SORT_VALUE = "date-desc";

const SORT_OPTIONS = [
	{ value: "date-desc", label: "Newest first" },
	{ value: "date-asc", label: "Oldest first" },
	{ value: "score-desc", label: "Highest score" },
	{ value: "score-asc", label: "Lowest score" },
] as const;

const REVIEW_OPTIONS = [
	{ value: "all", label: "Any reviewer" },
	{ value: "user", label: "Manual review" },
	{ value: "system", label: "Auto-classified" },
	{ value: "llm", label: "LLM-classified" },
] as const;

const APPROVAL_OPTIONS = [
	{ value: "all", label: "Any status" },
	{ value: "pending", label: "Pending approval" },
	{ value: "approved", label: "Approved" },
	{ value: "rejected", label: "Rejected" },
	{ value: "completed", label: "Completed" },
	{ value: "failed", label: "Failed" },
] as const;

function detectActiveBucket(types: string[] | undefined): Bucket {
	if (!types || types.length === 0) return "all";
	const set = new Set(types);
	for (const b of BUCKETS) {
		if (b.types.length === 0) continue;
		if (b.types.length === set.size && b.types.every((t) => set.has(t)))
			return b.key;
	}
	return "all";
}

