1	import { readFile, stat } from "node:fs/promises";
2	import { join, resolve } from "node:path";
3	import { sanitizeConversationId } from "@lobu/core";
4	import { filterChannelsForRequester } from "../../authz/channel-visibility.js";
5	import { type DbClient, getDb } from "../../db/client.js";
6	import {
7		resolveBoundChannelRows,
8		stripPlatformPrefix,
9	} from "../channels/bound-channels.js";
10	import { buildApiConversationId } from "./api-conversation-id.js";
11	import { listConversations } from "./conversations-store.js";
12	import { paginateSessionMessages } from "./session-message-page.js";
13	import { readSnapshotJsonl } from "./transcript-snapshot.js";
14	
15	const SAFE_AGENT_ID = /^[a-zA-Z0-9_-]+$/;
16	const SAFE_THREAD_ID = /^[a-zA-Z0-9_-]+$/;
17	
18	function isSafeAgentId(id: string): boolean {
19		return SAFE_AGENT_ID.test(id);
20	}
21	
22	function isSafeThreadId(id: string): boolean {
23		return SAFE_THREAD_ID.test(id);
24	}
25	
26	export interface AgentThreadSummary {
27		/** Routing key: a thread id for web conversations (chattable), or the raw
28		 *  conversation id for platform conversations (read-only). */
29		id: string;
30		title: string;
31		createdAt: number;
32		updatedAt: number;
33		/** "web" for the app's own threads; "behavior" for behavior activity; otherwise
34		 *  the source platform derived from the conversation id prefix (slack, …). */
35		platform: string;
36		/** Raw conversation id — used to read a platform conversation read-only. */
37		conversationId: string;
38		/** Set on `platform: "behavior"` entries — routes to the behavior's page. */
39		behaviorId?: number;
40	}
41	
42	/** `{platform}:{team}:{channel}` — team-scoped so the same channel id in two
43	 *  Slack workspaces never collides. `team` is "" for platforms without one. */
44	function channelVisibilityKey(
45		platform: string,
46		teamId: string | null,
47		bareChannelId: string,
48	): string {
49		return `${platform.toLowerCase()}:${teamId ?? ""}:${bareChannelId}`;
50	}
51	
52	export interface ChannelVisibility {
53		/** Team-scoped keys the requester may read (per-agent fence ∩ per-user ACL). */
54		visibleKeys: Set<string>;
55		/** `{platform}:{channel}` → the team ids the AGENT is bound to it in. A
56		 *  channel bound in >1 team can't be disambiguated from a conversation id
57		 *  alone, so it fails closed. */
58		channelTeams: Map<string, Set<string>>;
59	}
60	
61	/**
62	 * Which channels may THIS requester read for THIS agent — the per-agent channel
63	 * fence (the agent's bound channels) INTERSECTED with the per-user channel ACL
64	 * gate ({@link filterChannelsForRequester}), team-scoped. A platform conversation
65	 * is visible iff {@link isConversationVisible}. Mirrors recall's gate so a user
66	 * never sees a channel transcript they're not a member of.
67	 */
68	export async function resolveChannelVisibility(
69		sql: DbClient,
70		args: {
71			organizationId: string;
72			agentId: string;
73			userId: string | null;
74			allowNotGraphed?: boolean;
75		},
76	): Promise<ChannelVisibility> {
77		const bound = await resolveBoundChannelRows(sql, {
78			organizationId: args.organizationId,
79			agentId: args.agentId,
80		});
81		const channelTeams = new Map<string, Set<string>>();
82		for (const c of bound) {
83			const bare = stripPlatformPrefix(c.platform, c.channel_id);
84			const pc = `${c.platform.toLowerCase()}:${bare}`;
85			const set = channelTeams.get(pc) ?? new Set<string>();
86			set.add(c.team_id ?? "");
87			channelTeams.set(pc, set);
88		}
89		const visible = await filterChannelsForRequester(sql, {
90			organizationId: args.organizationId,
91			userId: args.userId,
92			rows: bound,
93			allowNotGraphed: args.allowNotGraphed,
94		});
95		const visibleKeys = new Set(
96			visible.map((c) =>
97				channelVisibilityKey(
98					c.platform,
99					c.team_id,
100					stripPlatformPrefix(c.platform, c.channel_id),
101				),
102			),
103		);
104		return { visibleKeys, channelTeams };
105	}
106	
107	/** Can the requester read this platform conversation (`{platform}:{channel}:{thread}`)?
108	 *  Fail-closed: unbound, or a channel bound in ≥2 DISTINCT REAL workspaces (can't
109	 *  tie the conversation to a single team), is not visible.
110	 *
111	 *  A NULL/"" team is a WILDCARD ("workspace unknown yet" — a binding written
112	 *  before its workspace healed from the first inbound event), NOT a distinct
113	 *  workspace. `team_id` is now guaranteed to be a real workspace or NULL (never a
114	 *  Grid enterprise id), so the gate needs zero connector knowledge: it counts
115	 *  distinct non-null teams and only fails closed on genuine cross-workspace
116	 *  ambiguity (2+ real teams). One real team + any number of NULLs resolves to
117	 *  that team; all-NULL resolves via the wildcard visible key. */
118	export function isConversationVisible(
119		conversationId: string,
120		vis: ChannelVisibility,
121	): boolean {
122		const parts = conversationId.split(":");
123		const platform = (parts[0] ?? "").toLowerCase();
124		const channel = parts[1] ?? "";
125		const teams = vis.channelTeams.get(`${platform}:${channel}`);
126		if (!teams || teams.size === 0) return false; // unbound
127		const realTeams = [...teams].filter((t) => t !== "");
128		if (realTeams.length > 1) return false; // genuine cross-workspace ambiguity
129		// One real team (NULLs are wildcards that resolve to it), or all-NULL (a
130		// teamless/unknown-yet binding — resolves via the "" wildcard visible key).
131		const team = realTeams[0] ?? null;
132		return vis.visibleKeys.has(channelVisibilityKey(platform, team, channel));
133	}
134	
135	async function findConversationSessionFile(
136		agentId: string,
137		conversationId: string,
138	): Promise<string | null> {
139		if (!isSafeAgentId(agentId)) return null;
140		const workspacesRoot = resolve("workspaces");
141		const workspaceDir = resolve(workspacesRoot, agentId);
142		if (!workspaceDir.startsWith(`${workspacesRoot}/`)) return null;
143	
144		const sanitized = sanitizeConversationId(conversationId);
145		const sessionPath = join(
146			workspaceDir,
147			sanitized,
148			".lobu",
149			"session.jsonl",
150		);
151		try {
152			await stat(sessionPath);
153			return sessionPath;
154		} catch {
155			return null;
156		}
157	}
158	
159	export async function listAgentThreads(args: {
160		agentId: string;
161		organizationId?: string;
162		userId: string;
163		/** "user" (default): only the requesting user's app threads. "all": every
164		 *  conversation for the agent across platforms (Slack, Telegram, …). */
165		scope?: "user" | "all";
166	}): Promise<AgentThreadSummary[]> {
167		const { agentId, organizationId, userId, scope = "user" } = args;
168		// No org → no tenant scope → nothing to list from the (org-keyed) entity.
169		if (!organizationId) return [];
170	
171		const byKey = new Map<string, AgentThreadSummary>();
172	
173		// Owned + platform conversations come from the `conversations` entity — the
174		// single listing source. This replaces the old
175		// `DISTINCT ON (conversation_id) FROM agent_transcript_snapshot` derive path
176		// AND the workspace-directory scan.
177		const rows = await listConversations({
178			organizationId,
179			agentId,
180			scope,
181			userId,
182		});
183	
184		// Platform ("all" scope) rows are ACL-gated: a platform conversation is only
185		// listed if its channel is in the agent's bound channels AND (for ACL-graphed
186		// connections) the requester is a member — so a user never sees a channel
187		// transcript they can't read.
188		let channelVis: ChannelVisibility | null = null;
189		if (scope === "all") {
190			channelVis = await resolveChannelVisibility(getDb(), {
191				organizationId,
192				agentId,
193				userId,
194			});
195		}
196	
197		for (const row of rows) {
198			const at = row.lastActivityAt.getTime();
199			const createdAt = row.createdAt.getTime();
200			if (row.kind === "owned") {
201				// Routable id is STORED (`thread_id`), never re-parsed out of the id
202				// string. The migration trigger also covers writes from an old server
203				// between the pre-upgrade migration and deployment replacement.
204				const threadId = row.threadId;
205				if (!threadId || !isSafeThreadId(threadId) || byKey.has(threadId)) {
206					continue;
207				}
208				byKey.set(threadId, {
209					id: threadId,
210					title: row.title ?? `Conversation ${byKey.size + 1}`,
211					createdAt,
212					updatedAt: at,
213					platform: "web",
214					conversationId: row.conversationId,
215				});
216			} else if (row.kind === "platform") {
217				// One entry per conversationId — that's the whole identity of a platform
218				// conversation (the connection that delivered it is routing, not identity;
219				// a reconnect changes it without changing the conversation). The ACL and
220				// transcript read address it by conversationId alone, consistent with this.
221				//
222				// isConversationVisible extracts platform:channel from the id, so an
223				// opaque/no-colon platform id fails closed (unlisted) — same as the prior
224				// path, which only ever listed `LIKE '%:%'` platform ids. Failing closed
225				// is safe; the same-channel-across-two-workspaces (Grid) case is likewise
226				// handled by isConversationVisible failing closed on team ambiguity.
227				if (byKey.has(row.conversationId)) continue;
228				if (channelVis && !isConversationVisible(row.conversationId, channelVis)) {
229					continue;
230				}
231				byKey.set(row.conversationId, {
232					id: row.conversationId,
233					title: row.title ?? row.conversationId,
234					createdAt,
235					updatedAt: at,
236					// Label from the EXPLICIT stored platform, not by parsing the id — an
237					// opaque/no-colon platform id (e.g. gchat spaces_A_threads_B) would
238					// otherwise mislabel as "web".
239					platform: row.platform,
240					conversationId: row.conversationId,
241				});
242			}
243		}
244	
245		// Watcher activity stays DERIVED from transcript snapshots — one entry per
246		// WATCHER (not per run), its latest run time + name, so the activity panel
247		// can route to the watcher's page. Watcher runs deliberately get no
248		// `conversations` row (their id is globally unique and downstream correlation
249		// relies on the raw `..._watcher_<id>_run_<id>` shape).
250		if (scope === "all") {
251			const sql = getDb();
252			const watcherRows = await sql<{
253				watcher_id: number;
254				name: string | null;
255				last_at: Date;
256			}>`
257	      SELECT w.id AS watcher_id, w.name, mx.last_at
258	      FROM (
259	        SELECT (regexp_match(conversation_id, '_watcher_([0-9]+)_run_'))[1]::int AS watcher_id,
260	               max(created_at) AS last_at
261	        FROM public.agent_transcript_snapshot
262	        WHERE organization_id = ${organizationId}
263	          AND agent_id = ${agentId}
264	          AND terminal_status = 'completed'
265	          AND conversation_id LIKE '%\\_watcher\\_%\\_run\\_%'
266	        GROUP BY 1
267	      ) mx
268	      JOIN public.watchers w ON w.id = mx.watcher_id
269	    `;
270			for (const row of watcherRows) {
271				const key = `watcher_${row.watcher_id}`;
272				const at = row.last_at.getTime();
273				byKey.set(key, {
274					id: key,
275					title: row.name ?? `Behavior ${row.watcher_id}`,
276					createdAt: at,
277					updatedAt: at,
278					platform: "behavior",
279					conversationId: key,
280					behaviorId: row.watcher_id,
281				});
282			}
283		}
284	
285		return [...byKey.values()].sort((a, b) => b.updatedAt - a.updatedAt);
286	}
287	
288	/**
289	 * Read one conversation's messages by its RAW conversation id (e.g. a platform
290	 * thread `slack:{channel}:{ts}`). Read-only — used to render platform
291	 * conversations that aren't routable through the app chat composer.
292	 */
293	export async function readConversationMessages(args: {
294		agentId: string;
295		organizationId: string;
296		conversationId: string;
297		cursor: string;
298		limit: number;
299	}) {
300		const { agentId, organizationId, conversationId, cursor, limit } = args;
301		const jsonl = await readSnapshotJsonl({
302			agentId,
303			organizationId,
304			conversationId,
305		});
306		if (jsonl === null) {
307			return {
308				messages: [],
309				nextCursor: null,
310				hasMore: false,
311				sessionId: conversationId,
312				threadId: conversationId,
313			};
314		}
315		return {
316			...paginateSessionMessages(jsonl, cursor, limit, {
317				excludeVerbose: true,
318				sessionIdFallback: conversationId,
319			}),
320			threadId: conversationId,
321		};
322	}
323	
324	export async function loadConversationTranscriptJsonl(
325		agentId: string,
326		organizationId: string | undefined,
327		conversationId: string,
328	): Promise<string | null> {
329		const fromDb = await readSnapshotJsonl({
330			agentId,
331			organizationId,
332			conversationId,
333		});
334		if (fromDb !== null) return fromDb;
335	
336		const sessionPath = await findConversationSessionFile(
337			agentId,
338			conversationId,
339		);
340		if (!sessionPath) return null;
341		return readFile(sessionPath, "utf-8");
342	}
343	
344	export async function readThreadMessages(args: {
345		agentId: string;
346		threadId: string;
347		cursor: string;
348		limit: number;
349		organizationId?: string;
350		userId: string;
351	}) {
352		const { agentId, threadId, cursor, limit, organizationId, userId } = args;
353		const conversationId = buildApiConversationId({
354			agentId,
355			userId,
356			organizationId,
357			threadId,
358		});
359	
360		const content = await loadConversationTranscriptJsonl(
361			agentId,
362			organizationId,
363			conversationId,
364		);
365		if (content === null) {
366			return {
367				messages: [],
368				nextCursor: null,
369				hasMore: false,
370				sessionId: conversationId,
371				threadId,
372			};
373		}
374	
375		return {
376			...paginateSessionMessages(content, cursor, limit, {
377				excludeVerbose: true,
378				sessionIdFallback: conversationId,
379			}),
380			threadId,
381		};
382	}
