2	 * Centralized event insertion.
3	 *
4	 * Every row in the `events` table should go through this module so we have
5	 * a single place for validation, defaults, and future hooks (e.g. embeddings).
6	 */
7	
8	import { retryWithBackoff } from '@lobu/core';
9	import { type DbClient, getDb } from '../db/client';
10	import { type ConfigResourceKind, redactConfigState } from './config-redaction';
11	import {
12	  lookupGeoEnrichment,
13	  mergeEnrichedMetadata,
14	} from './geo-enrichment';
15	import logger from './logger';
16	
17	/**
18	 * Single bounded retry for the fire-and-forget audit writers below
19	 * (recordChangeEvent / recordLifecycleEvent). One retry after a short delay
20	 * rides out transient DB blips (pool checkout timeout, failover) without
21	 * turning the audit path into a queue; a persistent failure is surfaced at
22	 * error level instead of being silently dropped.
23	 */
24	const AUDIT_EVENT_RETRY = { maxRetries: 1, baseDelay: 500 } as const;
25	
26	// Namespace for pg_advisory_xact_lock(key1, key2) used to serialize the
27	// dedup-on-(connection_id, origin_id) read-then-insert path below. Kept in the
28	// signed int32 range required by PostgreSQL's two-key advisory lock overload.
29	// "evdd" = events-dedup.
30	const EVENT_DEDUP_LOCK_NAMESPACE = 0x65766464;
31	
32	/**
33	 * Stable 32-bit FNV-1a hash of `connection_id:origin_id`, used as the second
34	 * key for pg_advisory_xact_lock. Concurrent ingests of the SAME item
35	 * (same connection + origin) serialize on this key; different items never
36	 * contend. Collisions only cost a little extra serialization, never
37	 * correctness.
38	 */
39	export function eventDedupLockKey(connectionId: number, originId: string): number {
40	  let hash = 0x811c9dc5;
41	  const s = `${connectionId}:${originId}`;
42	  for (let i = 0; i < s.length; i++) {
43	    hash ^= s.charCodeAt(i);
44	    hash = Math.imul(hash, 0x01000193);
45	  }
46	  return hash | 0;
47	}
