49	// ============================================
50	// Types
51	// ============================================
52	
53	interface InsertEventParams {
54	  entityIds: number[];
55	  organizationId: string;
56	  originId: string;
57	
58	  title?: string | null;
59	  payloadType?: 'text' | 'markdown' | 'json_template' | 'media' | 'empty';
60	  content?: string | null;
61	  payloadData?: Record<string, unknown>;
62	  payloadTemplate?: Record<string, unknown> | null;
63	  attachments?: unknown[];
64	  authorName?: string | null;
65	  sourceUrl?: string | null;
66	  occurredAt?: Date | string | null;
67	  semanticType: string;
68	  originType?: string | null;
69	  metadata?: Record<string, unknown>;
70	
71	  /** Connector-sourced fields */
72	  connectorKey?: string | null;
73	  connectionId?: number | null;
74	  feedKey?: string | null;
75	  feedId?: number | null;
76	  runId?: number | null;
