83	  interactionStatus?:
84	    | 'pending'
85	    | 'approved'
86	    | 'rejected'
87	    | 'completed'
88	    | 'failed'
89	    // Non-blocking suggested actions: 'current' while shown, superseded or
90	    // cleared by a later successful turn rather than resolved by a click.
91	    | 'current'
