102	}
103	
104	export interface InsertedEvent {
105	  id: number;
106	  entity_ids: number[] | null;
107	  origin_id: string;
108	  title: string | null;
109	  semantic_type: string;
110	  created_at: string;
111	  /** Whether this call landed a new immutable row or reused identical state. */
112	  change: 'inserted' | 'superseded' | 'unchanged';
113	}
114	
115	/** Key-order-independent JSON serialization for semantic equality checks. */
116	export function stableJson(value: unknown): string {
117	  if (value === null || typeof value !== 'object') return JSON.stringify(value);
118	  if (Array.isArray(value)) return `[${value.map((item) => stableJson(item)).join(',')}]`;
119	  const entries = Object.entries(value as Record<string, unknown>).sort(([a], [b]) =>
120	    a.localeCompare(b)
121	  );
122	  return `{${entries.map(([k, v]) => `${JSON.stringify(k)}:${stableJson(v)}`).join(',')}}`;
123	}
124	
125	function normalizedTimestamp(value?: Date | string | null): string | null {
126	  if (!value) return null;
127	  const date = value instanceof Date ? value : new Date(value);
128	  if (Number.isNaN(date.getTime())) return null;
129	  return date.toISOString();
130	}
131	
132	async function findCurrentEventByOrigin(
133	  sql: DbClient,
134	  params: InsertEventParams
135	): Promise<
136	  | {
137	      id: number;
138	      title: string | null;
139	      payload_text: string | null;
140	      payload_type: string;
141	      payload_data: Record<string, unknown>;
142	      payload_template: Record<string, unknown> | null;
143	      attachments: unknown[];
144	      author_name: string | null;
145	      source_url: string | null;
146	      occurred_at: string | null;
147	      semantic_type: string;
148	      origin_type: string | null;
149	      metadata: Record<string, unknown>;
150	      score: number | null;
151	      origin_parent_id: string | null;
152	      interaction_type: string;
153	      interaction_status: string | null;
154	      interaction_input_schema: Record<string, unknown> | null;
155	      interaction_input: Record<string, unknown> | null;
156	      interaction_output: Record<string, unknown> | null;
157	      interaction_error: string | null;
158	    }
159	  | undefined
160	> {
161	  if (!params.connectionId || !params.originId) return undefined;
162	
163	  const rows = await sql`
164	    SELECT e.id, e.title, e.payload_text, e.payload_type, e.payload_data, e.payload_template,
165	           e.attachments, e.author_name, e.source_url, e.occurred_at, e.semantic_type, e.origin_type,
166	           e.metadata, e.score, e.origin_parent_id, e.interaction_type, e.interaction_status,
167	           e.interaction_input_schema, e.interaction_input, e.interaction_output, e.interaction_error
168	    FROM events e
169	    WHERE e.organization_id = ${params.organizationId}
170	      AND e.connection_id = ${params.connectionId}
171	      AND e.origin_id = ${params.originId}
172	      AND NOT EXISTS (
173	        SELECT 1 FROM events newer WHERE newer.supersedes_event_id = e.id
174	      )
175	    ORDER BY e.created_at DESC, e.id DESC
176	    LIMIT 1
177	  `;
178	
179	  return rows[0] as any;
180	}
181	
182	function isSemanticallyEqual(
183	  existing: NonNullable<Awaited<ReturnType<typeof findCurrentEventByOrigin>>>,
184	  params: InsertEventParams
185	): boolean {
186	  return (
187	    (existing.title ?? null) === (params.title ?? null) &&
188	    (existing.payload_text ?? null) === (params.content ?? null) &&
189	    existing.payload_type === (params.payloadType ?? 'text') &&
190	    stableJson(existing.payload_data ?? {}) === stableJson(params.payloadData ?? {}) &&
191	    stableJson(existing.payload_template ?? null) === stableJson(params.payloadTemplate ?? null) &&
192	    stableJson(existing.attachments ?? []) === stableJson(params.attachments ?? []) &&
193	    (existing.author_name ?? null) === (params.authorName ?? null) &&
194	    (existing.source_url ?? null) === (params.sourceUrl ?? null) &&
195	    normalizedTimestamp(existing.occurred_at ?? null) ===
196	      normalizedTimestamp(params.occurredAt ?? null) &&
197	    existing.semantic_type === params.semanticType &&
198	    (existing.origin_type ?? null) === (params.originType ?? null) &&
199	    stableJson(existing.metadata ?? {}) === stableJson(params.metadata ?? {}) &&
200	    Number(existing.score ?? 0) === Number(params.score ?? 0) &&
201	    (existing.origin_parent_id ?? null) === (params.parentOriginId ?? null) &&
202	    existing.interaction_type === (params.interactionType ?? 'none') &&
203	    (existing.interaction_status ?? null) === (params.interactionStatus ?? null) &&
204	    stableJson(existing.interaction_input_schema ?? null) ===
205	      stableJson(params.interactionInputSchema ?? null) &&
206	    stableJson(existing.interaction_input ?? null) ===
207	      stableJson(params.interactionInput ?? null) &&
208	    stableJson(existing.interaction_output ?? null) ===
209	      stableJson(params.interactionOutput ?? null) &&
210	    (existing.interaction_error ?? null) === (params.interactionError ?? null)
211	  );
212	}
213	
214	async function upsertEmbedding(
215	  eventId: number,
216	  embedding: number[] | null | undefined,
217	  embeddingModel: string | null | undefined,
218	  sql: DbClient = getDb()
219	): Promise<void> {
220	  if (!embedding || embedding.length === 0) return;
221	  // An unstamped vector is unusable — search scopes vector comparison to the
222	  // configured model — so skip it and let the embed backfill produce a properly
223	  // stamped one.
224	  if (!embeddingModel) return;
225	  const vectorLiteral = `[${embedding.join(',')}]`;
226	  // Replace this (event, model)'s chunk set with a single chunk-0 row:
227	  // delete-then-insert scoped to the model so old/new models can coexist
228	  // during a zero-downtime swap (PK is event_id + embedding_model + chunk_index).
229	  await sql`DELETE FROM event_embeddings WHERE event_id = ${eventId} AND embedding_model = ${embeddingModel}`;
230	  await sql`
231	    INSERT INTO event_embeddings (event_id, chunk_index, embedding, embedding_model)
232	    VALUES (${eventId}, 0, ${vectorLiteral}::vector, ${embeddingModel})
233	  `;
234	}
235	
236	function isEventsClientIdForeignKeyViolation(error: unknown): boolean {
237	  const err = error as {
238	    code?: unknown;
239	    constraint?: unknown;
240	    constraint_name?: unknown;
241	    message?: unknown;
242	  };
243	  if (err?.code !== '23503') return false;
244	  return (
245	    err.constraint === 'events_client_id_fkey' ||
246	    err.constraint_name === 'events_client_id_fkey' ||
247	    (typeof err.message === 'string' && err.message.includes('events_client_id_fkey'))
248	  );
249	}
250	
251	/**
252	 * Insert a single event into the events table.
253	 *
254	 * Returns the inserted row (id, entity_ids, title, semantic_type, created_at).
255	 * If `onConflictUpdate` is true, performs an upsert on (connection_id, origin_id).
256	 * If `sql` is passed, the insert runs on that (transaction-bound) handle
257	 * instead of the singleton pool — used by the identity engine to keep its
258	 * fact + derivation writes atomic.
259	 */
260	export async function insertEvent(
261	  params: InsertEventParams,
262	  options?: {
263	    onConflictUpdate?: boolean;
264	    sql?: DbClient;
265	    /** Transactional hook for durable derived work such as Behavior runs. */
266	    afterPersist?: (event: InsertedEvent, sql: DbClient) => Promise<void>;
267	  }
268	): Promise<InsertedEvent> {
269	  const sql = options?.sql ?? getDb();
270	
271	  // Reverse-geocode lat/lng → city / admin1 / country once per event,
272	  // before insert. Silent no-op when the connector hasn't supplied
273	  // coordinates, when PostGIS / geo_places aren't seeded, or when the
274	  // nearest place is too far (ocean / desert). Connector-supplied
275	  // place_name etc. are preserved — enrichment only fills gaps.
276	  const enrichment = await lookupGeoEnrichment(params.metadata, { sql });
277	  const enrichedMetadata = mergeEnrichedMetadata(params.metadata, enrichment);
278	  if (enrichedMetadata !== params.metadata) {
279	    params = { ...params, metadata: enrichedMetadata };
280	  }
281	
282	  const entityIdsValue = params.entityIds.length > 0 ? `{${params.entityIds.join(',')}}` : null;
283	
284	  const requestedClientId = params.clientId ?? null;
285	
286	  // Core find→decide→insert, parameterized on the active SQL handle so it can
287	  // run either directly on the singleton pool or inside the dedup transaction
288	  // below (which holds an advisory lock for the duration).
289	  const runInsert = async (
290	    activeSql: DbClient
291	  ): Promise<InsertedEvent> => {
292	    let supersedesEventId = params.supersedesEventId ?? null;
293	
294	    if (options?.onConflictUpdate) {
295	      const existing = await findCurrentEventByOrigin(activeSql, params);
296	      if (existing) {
297	        if (isSemanticallyEqual(existing, params)) {
298	          // Reread before touching the embedding. If the row got
299	          // deleted / tombstoned between findCurrentEventByOrigin and
300	          // here, upsertEmbedding would FK-fail instead of letting us
301	          // fall through cleanly to a fresh insert (CodeRabbit catch
302	          // on PR #780).
303	          const existingRows = await activeSql`
304	            SELECT id, entity_ids, origin_id, title, semantic_type, created_at
305	            FROM events
306	            WHERE id = ${existing.id}
307	            LIMIT 1
308	          `;
309	          const existingRow = existingRows[0] as InsertedEvent | undefined;
310	          if (existingRow) {
311	            await upsertEmbedding(
312	              existingRow.id,
313	              params.embedding,
314	              params.embeddingModel,
315	              activeSql
316	            );
317	            const unchanged = { ...existingRow, change: 'unchanged' as const };
318	            await options?.afterPersist?.(unchanged, activeSql);
319	            return unchanged;
320	          }
321	          // Race: the existing row was deleted/tombstoned between the
322	          // findCurrentEventByOrigin lookup above and the SELECT here. Fall
323	          // through into the INSERT path with `supersedesEventId` unset so we
324	          // create a fresh row instead of crashing on `undefined.id`.
325	          logger.warn(
326	            { existingId: existing.id, originId: params.originId },
327	            '[insert-event] existing row vanished between find and reread — proceeding with fresh insert'
328	          );
329	        } else {
330	          supersedesEventId = existing.id;
331	        }
332	      }
333	    }
334	
335	    return insertRow(activeSql, supersedesEventId);
336	  };
337	
338	  const insertRow = async (
339	    sql: DbClient,
340	    supersedesEventId: number | null
341	  ): Promise<InsertedEvent> => {
342	    const insertWithClientId = (clientId: string | null) => sql`
343	    INSERT INTO events (
344	      entity_ids, organization_id, origin_id, title,
345	      payload_type, payload_text, payload_data, payload_template, attachments, metadata,
346	      score, author_name, source_url, occurred_at, origin_parent_id, origin_type,
347	      connector_key, connection_id, feed_key, feed_id, run_id,
348	      semantic_type, client_id, created_by,
349	      interaction_type, interaction_status, interaction_input_schema, interaction_input,
350	      interaction_output, interaction_error, supersedes_event_id
351	    ) VALUES (
352	      ${entityIdsValue}::bigint[],
353	      ${params.organizationId},
354	      ${params.originId},
355	      ${params.title ?? null},
356	      ${params.payloadType ?? 'text'},
357	      ${params.content ?? null},
358	      ${sql.json(params.payloadData ?? {})},
359	      ${params.payloadTemplate ? sql.json(params.payloadTemplate) : null},
360	      ${sql.json(params.attachments ?? [])},
361	      ${sql.json(params.metadata ?? {})},
362	      ${params.score ?? null},
363	      ${params.authorName ?? null},
364	      ${params.sourceUrl ?? null},
365	      ${params.occurredAt ?? null},
366	      ${params.parentOriginId ?? null},
367	      ${params.originType ?? null},
368	      ${params.connectorKey ?? null},
369	      ${params.connectionId ?? null},
370	      ${params.feedKey ?? null},
371	      ${params.feedId ?? null},
372	      ${params.runId ?? null},
373	      ${params.semanticType},
374	      ${clientId},
375	      ${params.createdBy ?? null},
376	      ${params.interactionType ?? 'none'},
377	      ${params.interactionStatus ?? null},
378	      ${params.interactionInputSchema ? sql.json(params.interactionInputSchema) : null},
379	      ${params.interactionInput ? sql.json(params.interactionInput) : null},
380	      ${params.interactionOutput ? sql.json(params.interactionOutput) : null},
381	      ${params.interactionError ?? null},
382	      ${supersedesEventId}
383	    )
384	    RETURNING id, entity_ids, origin_id, title, semantic_type, created_at
385	  `;
386	
387	  let result: Awaited<ReturnType<typeof insertWithClientId>>;
388	  try {
389	    result = await insertWithClientId(requestedClientId);
390	  } catch (error) {
391	    if (!requestedClientId || !isEventsClientIdForeignKeyViolation(error)) {
392	      throw error;
393	    }
394	    logger.warn(
395	      { clientId: requestedClientId },
396	      '[insert-event] retrying insert with client_id NULL — referenced oauth_clients row no longer exists'
397	    );
398	    result = await insertWithClientId(null);
399	  }
400	
401	  const inserted = result[0] as InsertedEvent | undefined;
402	  if (!inserted) {
403	    // INSERT ... RETURNING should always yield a row for a successful insert.
404	    // An empty result means either (a) a BEFORE INSERT trigger silently
405	    // RETURNed NULL (none in our schema today), or (b) postgres.js dropping
406	    // the rows for an obscure reason. Neither should drop events on the
407	    // floor — convert the cryptic `Cannot read
408	    // properties of undefined (reading 'id')` into a real error with
409	    // diagnostic context so we can root-cause when it next happens.
410	    logger.error(
411	      {
412	        originId: params.originId,
413	        connectionId: params.connectionId,
414	        organizationId: params.organizationId,
415	        semanticType: params.semanticType,
416	        connectorKey: params.connectorKey,
417	        feedKey: params.feedKey,
418	      },
419	      '[insert-event] INSERT ... RETURNING returned no rows — event not persisted'
420	    );
421	    throw new Error(
422	      `insertEvent: INSERT RETURNING came back empty for ` +
423	        `origin_id=${params.originId} connection_id=${params.connectionId}. ` +
424	        `Row was not persisted; check server logs for diagnostic context.`
425	    );
426	  }
427	
428	    // Dual-write the denormalized supersession edge. `events.superseded_by`
429	    // holds the inverse of `supersedes_event_id`: we stamp the row we just
430	    // replaced with the id of THIS new superseding row so live-row reads can
431	    // one day use `WHERE superseded_by IS NULL` instead of the per-row
432	    // anti-join in current_event_records. This touches LINEAGE METADATA ONLY,
433	    // never payload — the append-only invariant applies to content (precedent:
434	    // search_tsv is likewise maintained post-insert). Runs on the SAME `sql`
435	    // handle as the INSERT, so when we're inside the dedup advisory-lock tx or
436	    // a caller-supplied tx (identity engine) it is atomic with the supersede.
437	    //
438	    // The `AND superseded_by IS NULL` guard is belt-and-braces: the partial
439	    // unique index idx_events_superseded_by already fired a 23505 on the INSERT
440	    // above if the target was already superseded, so a 0-row UPDATE here can
441	    // only happen if the column was backfilled/stamped by a losing concurrent
442	    // writer whose INSERT nonetheless slipped through — in which case leaving
443	    // the existing stamp intact is correct (the unique index still guarantees a
444	    // single superseder).
445	    if (supersedesEventId !== null) {
446	      await sql`
447	        UPDATE events
448	        SET superseded_by = ${inserted.id}
449	        WHERE id = ${supersedesEventId}
450	          AND superseded_by IS NULL
451	      `;
452	    }
453	
454	    await upsertEmbedding(inserted.id, params.embedding, params.embeddingModel, sql);
455	    const persisted: InsertedEvent = {
456	      ...inserted,
457	      change: supersedesEventId === null ? 'inserted' : 'superseded',
458	    };
459	    await options?.afterPersist?.(persisted, sql);
460	    return persisted;
461	  };
462	
463	  // The dedup path (onConflictUpdate) is a non-atomic read-then-insert: it
464	  // looks up the current row for (connection_id, origin_id), then either
465	  // supersedes it or inserts fresh. Without serialization, two concurrent
466	  // ingests of the SAME item — common under N>1 app replicas and even two
467	  // overlapping runs on one replica — can both see "no current row" and both
468	  // insert with supersedes_event_id NULL (→ permanent duplicate current rows),
469	  // or both target the same row to supersede (→ duplicate-key error on
470	  // idx_events_superseded_by, which fails the whole stream batch). Hold a
471	  // transaction-scoped advisory lock keyed on (connection_id, origin_id) so
472	  // these serialize. Only engage when we own the connection (no caller-supplied
473	  // tx, which already runs in its own atomic scope) and have both keys.
474	  if (options?.onConflictUpdate && !options.sql && params.connectionId && params.originId) {
475	    const lockKey = eventDedupLockKey(params.connectionId, params.originId);
476	    return sql.begin(async (tx) => {
477	      await tx`
478	        SELECT pg_advisory_xact_lock(${EVENT_DEDUP_LOCK_NAMESPACE}, ${lockKey})
479	      `;
480	      return runInsert(tx);
481	    }) as Promise<InsertedEvent>;
482	  }
483	
484	  // An explicit supersede without a caller-supplied tx must still commit the
485	  // superseding INSERT and the superseded_by stamp atomically: as two
486	  // autocommit statements, a crash between them would leave the superseded
487	  // row's denormalized edge permanently NULL — which, after the Stage-2 view
488	  // flip to `WHERE superseded_by IS NULL`, would resurrect it as a live row.
489	  // (The dedup path can only derive a supersede when connectionId+originId are
490	  // both present, and that case is already inside the advisory-lock tx above.)
491	  if (params.supersedesEventId != null && !options?.sql) {
492	    return sql.begin(async (tx) =>
493	      runInsert(tx)
494	    ) as Promise<InsertedEvent>;
495	  }
496	
497	  return runInsert(sql);
498	}
499	
500	// ============================================
501	// Change Event (fire-and-forget audit trail)
502	// ============================================
503	
504	interface ChangeEventParams {
505	  entityIds: number[];
506	  organizationId: string;
507	  title: string;
508	  content: string;
509	  metadata: Record<string, unknown>;
510	  createdBy?: string | null;
511	  clientId?: string | null;
512	}
513	
514	/**
515	 * Record a change event for audit purposes.
516	 *
517	 * Fire-and-forget — never throws. Retries once after a short delay (the same
518	 * originId, so a retry can't double-write past a unique origin constraint);
519	 * if both attempts fail the dropped audit row is logged at ERROR with full
520	 * event context so it's visible in alerting rather than silently lost.
521	 * Used for entity updates, watcher archival, connection/feed deletion, etc.
522	 */
523	export function recordChangeEvent(params: ChangeEventParams): void {
524	  if (params.entityIds.length === 0) return;
525	
526	  const externalId = `change_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
527	
528	  retryWithBackoff(
529	    () =>
530	      insertEvent({
531	        entityIds: params.entityIds,
532	        organizationId: params.organizationId,
533	        originId: externalId,
534	        title: params.title,
535	        content: params.content,
536	        semanticType: 'change',
537	        metadata: params.metadata,
538	        createdBy: params.createdBy ?? null,
539	        clientId: params.clientId ?? null,
540	      }),
541	    AUDIT_EVENT_RETRY
542	  ).catch((err) => {
543	    logger.error(
544	      {
545	        err,
546	        originId: externalId,
547	        organizationId: params.organizationId,
548	        entityIds: params.entityIds,
549	        title: params.title,
550	        metadata: params.metadata,
551	      },
552	      '[insert-event] change audit event DROPPED after retry — audit trail is missing this row'
553	    );
554	  });
555	}
556	
557	// ============================================
558	// Lifecycle Event (entity create / update / delete)
559	// ============================================
560	
561	type LifecycleOp = 'created' | 'updated' | 'deleted';
562	
563	interface LifecycleEventParams {
564	  organizationId: string;
565	  /**
566	   * Entity-type slug used by dashboard SQL to pivot lifecycle rows
567	   * (`metadata->>'entity_type'`). Kept as a free-form string so new entity
568	   * types can emit without touching this file — keep slugs short, lowercase,
569	   * singular: `agent`, `connection`, `watcher`, `device`, `member`, `client`.
570	   */
571	  entityType: string;
572	  op: LifecycleOp;
573	  entityId: string | number;
574	  /** Human-readable summary (e.g. "Agent 'Marketing' created"). */
575	  summary: string;
576	  /** Optional extra metadata merged under `metadata.extra`. */
577	  extra?: Record<string, unknown>;
578	  createdBy?: string | null;
579	}
580	
581	/**
582	 * Record an entity-lifecycle change as a `semantic_type='change'` event.
583	 * Used by the metric_series SQL to compute cumulative counts (agents,
584	 * connections, …) and the dashboard sparklines. Fire-and-forget.
585	 *
586	 * Metadata shape (queryable via `metadata->>'category'`, etc.):
587	 *   {
588	 *     "category": "lifecycle",
589	 *     "entity_type": "connection",
590	 *     "op": "created",
591	 *     "entity_id": "...",
592	 *     "extra": { ... }    // optional
593	 *   }
594	 */
595	// ============================================
596	// Config Change Event (settings/deployment audit trail)
597	// ============================================
598	
599	type ConfigOp = 'created' | 'updated' | 'deleted';
600	type ConfigActorSource = 'cli' | 'ui' | 'api' | 'agent';
601	
602	interface ConfigChangeEventParams {
603	  organizationId: string;
604	  /** DiffRow-kind slug (`agent`, `agent-settings`, `connection`, ...). */
605	  resourceKind: ConfigResourceKind;
606	  resourceId: string | number;
607	  op: ConfigOp;
608	  /** Human-readable summary (e.g. "Agent 'Marketing' settings updated"). */
609	  summary: string;
610	  /**
611	   * Full post-change resource state (the row as written, including
612	   * server-merged fields — not the request body). Null for deletes and for
613	   * secret-only endpoints. Redacted by this writer before insert.
614	   */
615	  state: Record<string, unknown> | null;
616	  changedFields?: string[];
617	  /** `x-lobu-apply-id` when the mutation came from a `lobu apply` run. */
618	  applyId?: string | null;
619	  actorSource?: ConfigActorSource;
620	  createdBy?: string | null;
621	  clientId?: string | null;
622	}
623	
624	/**
625	 * Record a config mutation as a `semantic_type='change'` event with
626	 * `metadata.category='config'` and the full (redacted) post-change state in
627	 * `payload_data.state`. This is the settings audit trail behind the
628	 * Deployments feed; distinct from `category='lifecycle'` rows, which carry no
629	 * state and feed dashboard metric_series — handlers that emit lifecycle
630	 * events dual-write this one. Fire-and-forget, same retry/ERROR contract as
631	 * the writers above.
632	 */
633	export function recordConfigChangeEvent(params: ConfigChangeEventParams): void {
634	  const externalId = `config_${params.resourceKind}_${params.op}_${params.resourceId}_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
635	  const state = redactConfigState(params.resourceKind, params.state);
636	
637	  retryWithBackoff(
638	    () =>
639	      insertEvent({
640	        entityIds: [],
641	        organizationId: params.organizationId,
642	        originId: externalId,
643	        title: params.summary,
644	        semanticType: 'change',
645	        originType: `config_${params.resourceKind}_${params.op}`,
646	        payloadType: 'empty',
647	        payloadData: { state },
648	        metadata: {
649	          category: 'config',
650	          resource_kind: params.resourceKind,
651	          resource_id: String(params.resourceId),
652	          op: params.op,
653	          ...(params.changedFields?.length ? { changed_fields: params.changedFields } : {}),
654	          ...(params.applyId ? { apply_id: params.applyId } : {}),
655	          ...(params.actorSource ? { actor_source: params.actorSource } : {}),
656	        },
657	        createdBy: params.createdBy ?? null,
658	        clientId: params.clientId ?? null,
659	      }),
660	    AUDIT_EVENT_RETRY
661	  ).catch((err) => {
662	    logger.error(
663	      {
664	        err,
665	        originId: externalId,
666	        organizationId: params.organizationId,
667	        resourceKind: params.resourceKind,
668	        op: params.op,
669	        resourceId: String(params.resourceId),
670	        summary: params.summary,
671	      },
672	      '[insert-event] config audit event DROPPED after retry — audit trail is missing this row'
673	    );
674	  });
675	}
676	
677	export function recordLifecycleEvent(params: LifecycleEventParams): void {
678	  const externalId = `lifecycle_${params.entityType}_${params.op}_${params.entityId}_${Date.now()}`;
679	
680	  // Fire-and-forget with one bounded retry (same originId, so the retry is
681	  // safe against duplicate writes). A doubly-failed write is an ERROR — these
682	  // rows feed the dashboard metric_series, and a silent drop skews the
683	  // cumulative counts forever.
684	  retryWithBackoff(
685	    () =>
686	      insertEvent({
687	        entityIds: [],
688	        organizationId: params.organizationId,
689	        originId: externalId,
690	        title: params.summary,
691	        semanticType: 'change',
692	        originType: `${params.entityType}_${params.op}`,
693	        metadata: {
694	          category: 'lifecycle',
695	          entity_type: params.entityType,
696	          op: params.op,
697	          entity_id: String(params.entityId),
698	          ...(params.extra ? { extra: params.extra } : {}),
699	        },
700	        createdBy: params.createdBy ?? null,
701	      }),
702	    AUDIT_EVENT_RETRY
703	  ).catch((err) => {
704	    logger.error(
705	      {
706	        err,
707	        originId: externalId,
708	        organizationId: params.organizationId,
709	        entityType: params.entityType,
710	        op: params.op,
711	        entityId: String(params.entityId),
712	        summary: params.summary,
713	      },
714	      '[insert-event] lifecycle audit event DROPPED after retry — audit trail is missing this row'
715	    );
716	  });
717	}
