/**
 * Tool-invocation audit coverage (MCP-client activity ledger).
 *
 * `recordToolInvocationAudit` historically emitted only for `run_sdk` and
 * `query_sql`, so an external MCP client's session (ChatGPT, Claude, a PAT
 * script) left no trace of everything else it did — the activity surface had
 * nothing to group. This suite pins the widened contract:
 *   - every tool invoked with an EXTERNAL token (oauth/pat) writes an audit
 *     event, stamped with the persistent MCP session id when one exists;
 *   - browser-session and anonymous invocations do NOT get the generic
 *     fallback (the web app's own reads would flood the ledger) — run_sdk and
 *     query_sql keep their detailed audit for every token type;
 *   - `query_sql` audit records the `org_slug` redirect argument. A redirected
 *     call previously audited only the BOUND org, which read as "the redirect
 *     was silently ignored" during the run-757649 incident.
 */

import { beforeAll, describe, expect, it } from 'vitest';
import { getDb } from '../../../db/client';
import type { Env } from '../../../index';
import { type AuthContext, executeTool } from '../../../tools/execute';
import { cleanupTestDatabase } from '../../setup/test-db';
import {
  addUserToOrganization,
  createTestAccessToken,
  createTestOAuthClient,
  createTestOrganization,
  createTestUser,
  seedSystemEntityTypes,
} from '../../setup/test-fixtures';
import { ensureMcpSession, mcpToolsCall } from '../../setup/test-helpers';

interface AuditRow {
  payload_data: Record<string, unknown>;
  metadata: Record<string, unknown>;
  occurred_at: string | null;
}

async function latestAuditRow(orgId: string, toolName: string): Promise<AuditRow | null> {
  const sql = getDb();
  const rows = await sql<AuditRow[]>`
    SELECT payload_data, metadata, occurred_at
    FROM events
    WHERE organization_id = ${orgId}
      AND semantic_type = 'audit'
      AND origin_type = 'tool_invocation'
      AND payload_data->>'tool_name' = ${toolName}
    ORDER BY id DESC
    LIMIT 1
  `;
  return rows[0] ?? null;
}

describe('tool invocation audit coverage', () => {
  let token: string;
  let orgId: string;
  let orgSlug: string;
  let ownerId: string;
  let clientId: string;

  beforeAll(async () => {
    await cleanupTestDatabase();
    await seedSystemEntityTypes();
    const org = await createTestOrganization({
      name: 'Audit Coverage Org',
      slug: 'audit-coverage-org',
    });
    orgId = org.id;
    orgSlug = org.slug;
    const owner = await createTestUser({ email: 'audit-coverage@test.example.com' });
    ownerId = owner.id;
    await addUserToOrganization(owner.id, org.id, 'owner');
    const oauthClient = await createTestOAuthClient();
    clientId = oauthClient.client_id;
    token = (
      await createTestAccessToken(owner.id, org.id, oauthClient.client_id, {
        scope: 'mcp:read mcp:write mcp:admin',
      })
    ).token;
  });

  function authCtxFor(tokenType: 'oauth' | 'pat' | 'session'): AuthContext {
    return {
      organizationId: orgId,
      tokenOrganizationId: tokenType === 'session' ? null : orgId,
      userId: ownerId,
      memberRole: 'owner',
      agentId: null,
      requestedAgentId: null,
      isAuthenticated: true,
      clientId: tokenType === 'oauth' ? clientId : null,
      scopes: tokenType === 'session' ? null : ['mcp:read', 'mcp:write', 'mcp:admin'],
      tokenType,
      requestUrl: 'http://localhost/lobu/tools/test',
      baseUrl: 'http://localhost',
      scopedToOrg: false,
      allowCrossOrg: tokenType === 'oauth',
    };
  }

  it('audits a generic (non run_sdk/query_sql) tool call from an MCP oauth session, stamped with the session id', async () => {
    await mcpToolsCall(
      'get_content',
      { limit: 1 },
      { token, orgSlug }
    );
    const sessionId = await ensureMcpSession({ token, orgSlug });

    const row = await latestAuditRow(orgId, 'get_content');
    expect(row).not.toBeNull();
    expect(row!.payload_data.success).toBe(true);
    expect(row!.payload_data.args_sha256).toEqual(expect.any(String));
    expect(row!.payload_data.args_preview_redacted).toContain('limit');
    // No raw result payload — the audit is a ledger of WHO did WHAT, not a copy
    // of the data that was read.
    expect(row!.payload_data).not.toHaveProperty('content');
    expect(row!.metadata.mcp_session_id).toBe(sessionId);
    expect(row!.occurred_at).not.toBeNull();
  });

  it('records the org_slug redirect argument on query_sql audit rows', async () => {
    const result = (await executeTool(
      'query_sql',
      { sql: 'SELECT id FROM events', sort_by: 'id', limit: 1, org_slug: orgSlug },
      {} as Env,
      authCtxFor('oauth')
    )) as { error?: string };
    expect(result.error).toBeUndefined();

    const row = await latestAuditRow(orgId, 'query_sql');
    expect(row).not.toBeNull();
    expect(row!.payload_data.org_slug).toBe(orgSlug);
    // REST/proxy invocations have no MCP session — stamped as null, not absent.
    expect(row!.metadata).toHaveProperty('mcp_session_id', null);
  });

  it('does NOT write generic audit rows for browser-session tool calls', async () => {
    const before = await latestAuditRow(orgId, 'list_connections');
    expect(before).toBeNull();

    await executeTool('list_connections', {}, {} as Env, authCtxFor('session'));

    expect(await latestAuditRow(orgId, 'list_connections')).toBeNull();
  });

  it('still audits query_sql for browser-session callers (detailed audit is token-type independent)', async () => {
    await executeTool(
      'query_sql',
      { sql: 'SELECT id FROM entities', sort_by: 'id', limit: 1 },
      {} as Env,
      authCtxFor('session')
    );

    const sql = getDb();
    const rows = await sql`
      SELECT id FROM events
      WHERE organization_id = ${orgId}
        AND semantic_type = 'audit'
        AND payload_data->>'tool_name' = 'query_sql'
        AND payload_data->>'sql_preview_redacted' LIKE '%FROM entities%'
    `;
    expect(rows).toHaveLength(1);
  });

  it('audits a failed generic call with the error captured', async () => {
    await expect(
      executeTool('manage_connections', { action: 'nope' }, {} as Env, authCtxFor('pat'))
    ).rejects.toThrow();

    const row = await latestAuditRow(orgId, 'manage_connections');
    expect(row).not.toBeNull();
    expect(row!.payload_data.success).toBe(false);
    expect(row!.payload_data.error).toBeTruthy();
  });
});

