8	const MAX_PREVIEW_CHARS = 500;
9	const SENSITIVE_ASSIGNMENT_RE =
10	  /(api[_-]?key|authorization|cookie|credential|password|private[_-]?key|secret|token)\s*["']?\s*[:=]\s*["']?[^\s,'"}]+/gi;
11	const BEARER_TOKEN_RE = /bearer\s+[a-z0-9._~+\/-]+/gi;
12	
13	interface ToolInvocationAuditParams {
14	  toolName: string;
15	  args: Record<string, unknown>;
16	  result?: unknown;
17	  error?: unknown;
18	  durationMs: number;
19	  ctx: ToolContext;
20	}
