22	function sha256(value: string): string {
23	  return createHash('sha256').update(value).digest('hex');
24	}
25	
26	function redactSensitiveText(value: string): string {
27	  return value
28	    .replace(BEARER_TOKEN_RE, 'Bearer [redacted]')
29	    .replace(SENSITIVE_ASSIGNMENT_RE, (_match, key: string) => `${key}=[redacted]`);
30	}
31	
32	function redactPreview(value: string): string {
33	  return redactSensitiveText(value.slice(0, MAX_PREVIEW_CHARS));
34	}
35	
36	function stringifyRedacted(value: unknown): string {
37	  return JSON.stringify(deepRedactSecrets(value), (_key, nestedValue) =>
38	    typeof nestedValue === 'string' ? redactSensitiveText(nestedValue) : nestedValue
39	  );
40	}
41	
42	function asObject(value: unknown): Record<string, unknown> {
43	  return value && typeof value === 'object' && !Array.isArray(value)
44	    ? (value as Record<string, unknown>)
45	    : {};
46	}
47	
48	function errorPayload(
49	  error: unknown,
50	  fallbackName: string = 'Error'
51	): Record<string, unknown> | null {
52	  if (!error) return null;
53	  if (error instanceof Error) {
54	    return { name: error.name, message: redactPreview(error.message) };
55	  }
56	  if (typeof error === 'object') {
57	    const record = error as Record<string, unknown>;
58	    return {
59	      name: typeof record.name === 'string' ? record.name : fallbackName,
60	      message:
61	        typeof record.message === 'string'
62	          ? redactPreview(record.message)
63	          : stringifyRedacted(record).slice(0, MAX_PREVIEW_CHARS),
64	    };
65	  }
66	  return { name: fallbackName, message: redactPreview(String(error)) };
67	}
