69	function buildPayload(params: ToolInvocationAuditParams): Record<string, unknown> | null {
70	  const result = asObject(params.result);
71	  const toolError = params.error ? errorPayload(params.error) : null;
72	
73	  if (params.toolName === 'run_sdk') {
74	    const script = typeof params.args.script === 'string' ? params.args.script : '';
75	    const resultError = errorPayload(result.error);
76	    return {
77	      tool_name: params.toolName,
78	      dry_run: params.args.dry_run === true,
79	      script_sha256: script ? sha256(script) : null,
80	      script_preview_redacted: script ? redactPreview(script) : null,
81	      sdk_call_count: typeof result.sdk_calls === 'number' ? result.sdk_calls : null,
82	      sdk_call_trace: Array.isArray(result.sdk_call_trace) ? result.sdk_call_trace : [],
83	      side_effect_preview: Array.isArray(result.side_effect_preview)
84	        ? result.side_effect_preview
85	        : [],
86	      side_effect_count: Array.isArray(result.side_effect_preview)
87	        ? result.side_effect_preview.length
88	        : 0,
89	      success: toolError ? false : result.success === true,
90	      error: toolError ?? resultError,
91	      duration_ms: params.durationMs,
92	    };
93	  }
94	
95	  if (params.toolName === 'query_sql') {
96	    const sql = typeof params.args.sql === 'string' ? params.args.sql : '';
97	    const resultError =
98	      typeof result.error === 'string'
99	        ? { name: 'QuerySqlError', message: redactPreview(result.error) }
100	        : null;
101	    return {
102	      tool_name: params.toolName,
103	      sql_sha256: sql ? sha256(sql) : null,
104	      sql_preview_redacted: sql ? redactPreview(sql) : null,
105	      // The event stays in the bound org, so retain the requested target.
106	      org_slug: typeof params.args.org_slug === 'string' ? params.args.org_slug : null,
107	      sort_by: typeof params.args.sort_by === 'string' ? params.args.sort_by : null,
108	      sort_order: params.args.sort_order === 'desc' ? 'desc' : 'asc',
109	      limit: typeof params.args.limit === 'number' ? params.args.limit : null,
110	      offset: typeof params.args.offset === 'number' ? params.args.offset : null,
111	      row_count: Array.isArray(result.rows) ? result.rows.length : 0,
112	      total_count: typeof result.total_count === 'number' ? result.total_count : null,
113	      success: !(toolError || resultError),
114	      error: toolError ?? resultError,
115	      duration_ms: params.durationMs,
116	    };
117	  }
118	
119	  // Browser-session and anonymous reads would generate an event per page view;
120	  // only externally authenticated calls belong in the client activity ledger.
121	  if (params.ctx.tokenType !== 'oauth' && params.ctx.tokenType !== 'pat') {
122	    return null;
123	  }
124	  const argsJson = JSON.stringify(params.args ?? {});
125	  const redactedArgsJson = stringifyRedacted(params.args ?? {});
126	  const resultError = errorPayload(result.error, 'ToolError');
127	  const reportedFailure = result.success === false || result.status === 'failed';
128	  const softError =
129	    resultError ??
130	    (reportedFailure
131	      ? errorPayload(
132	          result.error_message ?? result.message ?? 'Tool reported failure',
133	          'ToolError'
134	        )
135	      : null);
136	  return {
137	    tool_name: params.toolName,
138	    args_sha256: sha256(argsJson),
139	    args_preview_redacted: redactedArgsJson.slice(0, MAX_PREVIEW_CHARS),
140	    success: !(toolError || softError),
141	    error: toolError ?? softError,
142	    duration_ms: params.durationMs,
143	  };
144	}
