    result.success === false ||
    result.status === 'failed' ||
        result.status === 'timeout';
  const softError =
    resultError ??
    (reportedFailure
      ? errorPayload(
          result.error_message ?? result.message ?? 'Tool reported failure',
          'ToolError'
