import { createFileRoute, Outlet } from "@tanstack/react-router";

/**
 * Connect layout for every /connectors/* surface: list, create, connector
 * detail, connection, and feed. The sidebar owns the primary Connect
 * destination; this layout only provides shared page padding.
 *
 * Width is full main pane — connector/connection pages need room for rails;
 * the list centers its own max-w-3xl column.
 */
export const Route = createFileRoute("/$owner/connectors")({
	component: ConnectorsLayout,
});

function ConnectorsLayout() {
	return (
		<div className="flex min-h-0 flex-1 flex-col gap-4 px-4 py-6 lg:px-6">
			<div className="flex min-h-0 min-w-0 flex-1 flex-col">
				<Outlet />
			</div>
		</div>
	);
}
