import { createFileRoute, Outlet } from "@tanstack/react-router";

/**
 * Layout for device pairing routes under /connectors/runtime.
 * Index is devices-only (sandboxes are connectors-list rows); device detail
 * lives in `runtime/devices/$deviceId.tsx`.
 *
 * `validateSearch` keeps `?provider=` typed for back-compat with old sandbox
 * deep links that still hit this path.
 */
export const Route = createFileRoute("/$owner/connectors/runtime")({
	validateSearch: (search: Record<string, unknown>) => ({
		provider: typeof search.provider === "string" ? search.provider : undefined,
	}),
	component: () => <Outlet />,
});

