			const data = (await res.json()) as { sessions?: ClientSessionItem[] };
			return data.sessions ?? [];
		},
		enabled: !!slug && (options?.enabled ?? true),
		staleTime: 15_000,
		refetchInterval: options?.refetchInterval,
	});
}

